(6365562, 942698, 24454, '<td valign="top">Yes!  If I were handing out the ribbons, this one would be in first place.  The artistry is beautiful, and would make a great large framed print for a child''s room.</td>', 'Yes!  If I were handing out the ribbons, this one would be in first place.  The artistry is beautiful, and would make a great large framed print for a child''s room.', '2011-03-28 17:16:12.000000', NULL, 1),
(6365565, 942473, 24454, '<td valign="top">This is very good!! Beautiful job! 10</td>', 'This is very good!! Beautiful job! 10', '2011-03-28 17:19:18.000000', NULL, 1),
