(6365900, 942705, 13688, '<td valign="top">with the ever present security cam...nice</td>', 'with the ever present security cam...nice', '2011-03-29 00:35:26.000000', NULL, 1),
(6365907, 942632, 13688, '<td valign="top">nice flow...too bad you didn''t get a clear blue sky.</td>', 'nice flow...too bad you didn''t get a clear blue sky.', '2011-03-29 00:49:44.000000', NULL, 1),
(6365909, 942875, 13688, '<td valign="top">intriguing...wish you gave it much more space around the edges...like smaller with 100px of black border.</td>', 'intriguing...wish you gave it much more space around the edges...like smaller with 100px of black border.', '2011-03-29 00:55:34.000000', NULL, 1),
(6365919, 942606, 13688, '<td valign="top">When irish eggs are smiling?  Interesting group dynamic.</td>', 'When irish eggs are smiling?  Interesting group dynamic.', '2011-03-29 01:04:57.000000', NULL, 1),
(6365921, 942365, 13688, '<td valign="top">technically very nice, but your next challenge is to photograph all 13 lit.</td>', 'technically very nice, but your next challenge is to photograph all 13 lit.', '2011-03-29 01:07:34.000000', NULL, 1),
(6365931, 942671, 13688, '<td valign="top">i know the odds must be pretty slim running into a pack of 13 alpacas...i would have made that un-attentive one into a ball of yarn on the spot.</td>', 'i know the odds must be pretty slim running into a pack of 13 alpacas...i would have made that un-attentive one into a ball of yarn on the spot.', '2011-03-29 01:14:09.000000', NULL, 1),
(6365935, 943018, 13688, '<td valign="top">i feel like i''ve fallen and i can''t get up...not that that''s a bad thing.</td>', 'i feel like i''ve fallen and i can''t get up...not that that''s a bad thing.', '2011-03-29 01:16:08.000000', NULL, 1),
(6365943, 943085, 1686, '<td valign="top">the color is fabulous , unfortunately the focus is a bit soft</td>', 'the color is fabulous , unfortunately the focus is a bit soft', '2011-03-29 01:25:25.000000', NULL, 1),
(6365949, 942755, 13688, '<td valign="top">i like that i recognized that the 13 was one of the 13 balls.  I''m not so sure i like vibrant colors forced into black and white, though someone else black and whited their strawberries, so perhaps I don''t know what I''m talking about.</td>', 'i like that i recognized that the 13 was one of the 13 balls.  I''m not so sure i like vibrant colors forced into black and white, though someone else black and whited their strawberries, so perhaps I don''t know what I''m talking about.', '2011-03-29 01:30:13.000000', NULL, 1),
(6365951, 943150, 13688, '<td valign="top">this seems like a great stock art idea, but your lighting needs to be equal and your bills need to at least all be right side up.  it would probably also be helpful if it didn''t run over the edge and there was some sort of path to better lead the eye into the maze.</td>', 'this seems like a great stock art idea, but your lighting needs to be equal and your bills need to at least all be right side up.  it would probably also be helpful if it didn''t run over the edge and there was some sort of path to better lead the eye into the maze.', '2011-03-29 01:34:11.000000', NULL, 1),
(6365956, 942856, 13688, '<td valign="top">i like the x you created with the legs... adds to the iconography on the door.  Don''t get the shoelace, but I never read the bible, so I''ll just assume you know what you''re doing.</td>', 'i like the x you created with the legs... adds to the iconography on the door.  Don''t get the shoelace, but I never read the bible, so I''ll just assume you know what you''re doing.', '2011-03-29 01:40:56.000000', NULL, 1),
