INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6376893, 943072, 44877, '<td valign="top">How funny! Greetings from the Critique Club! You asked for an in-depth critique and here we go: <br/> <br/>There''s not a whole lot I could say that you haven''t heard from me already. Regardless - I really love this image. It is a completely original and personal take on the challenge topic, and I can see by the comments that you hit a nerve with the viewers/voters. There are many slick images out there, but in the end, the photo that touches people is the one that counts. <br/> <br/>Your post processing is very original and emphasizes the subject (the pills) without being pretentious. The composition is good with the angle of the hand, the background telling more of the story, and lastly the positioning of the pills themselves. <br/> <br/>Some challenges - The lighting is a little harsh where it hits the thumb. An additional light source might have helped with that. The bottom right corner is a little distracting because of the light ridge of the table. Since this is advanced editing, you could have perhaps burned that ridge to make it blend in a little. This way the eye sort of wanders there. <br/> <br/>Congratulations on your first entry and on a great score!<br/> <br/>Alicia</td>', 'How funny! Greetings from the Critique Club! You asked for an in-depth critique and here we go:  There''s not a whole lot I could say that you haven''t heard from me already. Regardless - I really love this image. It is a completely original and personal take on the challenge topic, and I can see by the comments that you hit a nerve with the viewers/voters. There are many slick images out there, but in the end, the photo that touches people is the one that counts.  Your post processing is very original and emphasizes the subject (the pills) without being pretentious. The composition is good with the angle of the hand, the background telling more of the story, and lastly the positioning of the pills themselves.  Some challenges - The lighting is a little harsh where it hits the thumb. An additional light source might have helped with that. The bottom right corner is a little distracting because of the light ridge of the table. Since this is advanced editing, you could have perhaps burned that ridge to make it blend in a little. This way the eye sort of wanders there.  Congratulations on your first entry and on a great score! Alicia', '2011-04-06 17:28:48.000000', NULL, 0),
(6376907, 942538, 44877, '<td valign="top">Greetings from the Critique Club! You asked for an in-depth critique of your image and here it is: <br/> <br/>Congratulations on placing top 20 in a very open-ended challenge. Your image is well executed as also reflected by your decent score. <br/> <br/>The concept is good - not only 13 matches and one burning, but there is a progression in the burned matches, which creates some visual interest. The light source seems to be coming from the left, and as such illuminates the first half of the matches pretty well. Further to the right, though, the lighting is a little challenged, and I find myself squinting to make out more detail in that part of the image. The lighting or lack thereof is also what makes the right part somewhat flat. That would be my only technical critique for this photo.<br/> <br/>Conceptionally it''s cute, no real content. Here on this site that is rewarded nonetheless. The border really brings this photo together - good choice in using it as you did. <br/> <br/>Best wishes, <br/> <br/>Alicia</td>', 'Greetings from the Critique Club! You asked for an in-depth critique of your image and here it is:  Congratulations on placing top 20 in a very open-ended challenge. Your image is well executed as also reflected by your decent score.  The concept is good - not only 13 matches and one burning, but there is a progression in the burned matches, which creates some visual interest. The light source seems to be coming from the left, and as such illuminates the first half of the matches pretty well. Further to the right, though, the lighting is a little challenged, and I find myself squinting to make out more detail in that part of the image. The lighting or lack thereof is also what makes the right part somewhat flat. That would be my only technical critique for this photo. Conceptionally it''s cute, no real content. Here on this site that is rewarded nonetheless. The border really brings this photo together - good choice in using it as you did.  Best wishes,  Alicia', '2011-04-06 17:36:13.000000', NULL, 0),
(6376924, 942930, 44877, '<td valign="top">Greetings from the Critique Club! You asked for an in-depth critique on your image and here it is: <br/> <br/>First response is a snicker - Beans! What an idea... I wonder how you came up with it. The little ends of the beans give this a whimsical flair. The color is good, and the background color also works to compliment the green of the beans. Reflections add an extra dimension. Lighting is good, as well. <br/> <br/>This image has no content to speak of, but then you read the title and stop short. Perhaps it''s just me - but I feel the title is a bit of a non sequitur in the face of beans. The depth of field is a little off - the beans on the outer limits are out of focus. And lastly, I feel the border is a bit heavy. <br/> <br/>You scored very well - good for you! <br/> <br/>Best wishes, <br/> <br/>Alicia<br/> <br/></td>', 'Greetings from the Critique Club! You asked for an in-depth critique on your image and here it is:  First response is a snicker - Beans! What an idea... I wonder how you came up with it. The little ends of the beans give this a whimsical flair. The color is good, and the background color also works to compliment the green of the beans. Reflections add an extra dimension. Lighting is good, as well.  This image has no content to speak of, but then you read the title and stop short. Perhaps it''s just me - but I feel the title is a bit of a non sequitur in the face of beans. The depth of field is a little off - the beans on the outer limits are out of focus. And lastly, I feel the border is a bit heavy.  You scored very well - good for you!  Best wishes,  Alicia ', '2011-04-06 17:44:58.000000', NULL, 0),
